def place(shop):
    return shop.orders.handle_create(
        {"customer_id": "c1", "items": [{"sku": "LAMP", "quantity": 2}, {"sku": "BOOK", "quantity": 1}]}
    ).body["order_id"]


def test_packing_slip_for_unknown_order_is_not_found(shop):
    response = shop.fulfilment.handle_packing_slip("nope")
    assert (response.status, response.body) == (404, {"error": "order not found"})


def test_packing_slip_for_cancelled_order_is_a_conflict(shop):
    order_id = place(shop)
    shop.orders.handle_cancel(order_id)
    response = shop.fulfilment.handle_packing_slip(order_id)
    assert response.status == 409
    assert response.body["error"]


def test_packing_slip_lists_customer_and_lines_in_item_order(shop):
    order_id = place(shop)
    response = shop.fulfilment.handle_packing_slip(order_id)
    assert response.status == 200
    assert response.body == {
        "order_id": order_id,
        "customer_name": "Ada",
        "lines": [
            {"sku": "LAMP", "name": "Lamp", "quantity": 2},
            {"sku": "BOOK", "name": "Book", "quantity": 1},
        ],
    }

